syms='ABCDEFGHI'
# generate all surjective colorings of 9 symbols into 3 colors with each size 3, fixing A->0 and next smallest unassigned in first absent color etc to remove symm? We'll brute via choosing color0 set containing A, then color1 min... 
res=[]
letters=list(syms)
others=letters[1:]
count=0
for comb0 in itertools.combinations(others,2):
    set0={'A',*comb0}
    rem=[x for x in letters if x not in set0]
    first=rem[0]
    for comb1 in itertools.combinations(rem[1:],2):
        set1={first,*comb1}
        set2=set(rem)-set1
        # labeling by set0,set1,set2
        color={x:(0 if x in set0 else 1 if x in set1 else 2) for x in letters}
        mp={}
        ok=True
        for a,b,c in itertools.product(letters, repeat=3):
            key=(color[a],color[b],color[c])
            out=color[table[a+b+c]]
